head.script:
// 결함 재현 시나리오 설명
scwin.tData = {
    "description" : "[FAIL] inputCalendar renderType=native 일 때 setValue() 호출 후 팝업 달력의 '이전해' 버튼 클릭 시 onyearselect.info.oldValue 가 setValue 한 연도가 아닌 시스템 현재 연도 기준으로 발생하는 결함 재현",
    "validation" : [
        "renderType=native 일 때 setValue('20251111') 호출 후 팝업 달력의 '이전해' 버튼 클릭 시 onyearselect.info.oldValue 가 setValue 한 연도(2025) 로 발생해야 합니다.",
        "현재 실제 동작 : info.oldValue 가 시스템 현재 연도로 발생 (setValue 로 설정한 연도가 무시됨)."
    ]
}



scwin.onpageload = function () {
    // 페이지 로드 후 컴포넌트 렌더링 완료 시점에 setValue 적용
    Promise.resolve().then(function () {
        scwin.btn_setValue_onclick();
    });
};



// setValue('20251111') 호출 후 현재 상태 출력
scwin.btn_setValue_onclick = function () {
    target_native.setValue("20251111");

    var sysYear = new Date().getFullYear();
    scwin.setReturnValue("─── setValue('20251111') 호출 완료 ───");
    scwin.setReturnValue("시스템 현재 연도 : " + sysYear);
    scwin.setReturnValue("getValue() : " + target_native.getValue());
    scwin.setReturnValue("");
    scwin.setReturnValue("기대 동작 : '이전 해' 클릭 시 info.oldValue = 2025 (setValue 한 연도)");
    scwin.setReturnValue("실제 동작 : info.oldValue = " + sysYear + " (시스템 현재 연도)");
    scwin.setReturnValue("");
    scwin.setReturnValue("재현 방법 : 달력 아이콘 클릭 → 팝업 상단의 '이전 해' 버튼 클릭");
    scwin.setReturnValue("");
};



// renderType=native 의 onyearselect 결과 출력 (결함 발생)
scwin.target_native_onyearselect = function (info) {
    scwin.setReturnValue("[onyearselect] info.oldValue=" + info.oldValue + " / info.newValue=" + info.newValue + " (기대 oldValue : 2025, 실제 : 시스템 현재 연도)");
};



// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정 (독립 실행용)
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
